`timescale 1ns/1ps
module hex_to_rtl_top_tb ();

logic clk;
logic rst;
logic [1023:0] data_in;
logic data_in_sop;
logic data_in_eop;
logic data_in_valid;
logic data_in_ready;
logic path_id_out_ready;
logic [13 - 1:0] path_id_out;
logic path_id_out_valid;

// Clock generation
initial begin
    clk = 1'b0;
    forever #5 clk = ~clk;
end

// Stimulus vector
logic [1024-1:0] stimulus_vec [0:1];

initial begin
    stimulus_vec = {
        1024'h6dde925c066278cde651abd7080045a7e4715275422b39065723C0A801640A00003252e20050f447041e46180bfe53f996b02ebef80c474554202Fd9e3644ac6f3b9235a5120a6d13f63140fcf938b4f9c4c439a9333f896fc27e4ef069040a0851a49223e8b07a6072013d21c1fd630e94305a1f9bc30ea5315162b92d0b475,
        1024'h68d2db5eb5ec94b8ecaedd27080045d8c1bff4bfd4849f01aa620A0000010A0000021650bceff351970308001ce818e3642fd8fb04799bb801e303cabfa5a3eeba0a3a662255d7c36f686ae29aeeffe20f2080ff897ef6476e474a7af181bbcffff6db075a9d650303728b983ac9ab242edfce0851c91dcfef5679061f80d6bf
    };
end

// Golden output queue
logic [13-1:0] golden_q[$] =  {
    13'b0000000001010,
    13'b0011000000110
};


//Driving Stimulus to DUT
initial begin
    $dumpfile("hex_to_rtl_top_tb.vcd");
    $dumpvars(0, hex_to_rtl_top_tb);
    rst = 1;
    data_in = '0;
    data_in_valid = '0;
    path_id_out_ready = 1'b1;
    #20;
    rst = 0;
    data_in_sop = '0;
    data_in_eop = '0;

    // Send packets
    for (int ii = 0; ii < 2; ii = ii + 1) begin

      @(posedge clk);
      data_in_valid = 1'b1;
      data_in_sop = 1'b1;
      data_in_eop = 1'b1;
      data_in = stimulus_vec[ii][1023 -: 1024];

      @(posedge clk);
      data_in  = '0;
      data_in_valid = 1'b0;
      data_in_sop = 1'b0;
      data_in_eop = 1'b0;

      // Idle cycles between packets -- generous enough to drain the
      // comparison/lookup pipeline before the next SOP, so a new packet
      // can't reset flit_counter mid-flight and corrupt path_id_out.
      repeat ($urandom_range(3, 6)) @(posedge clk);
    end

    // Finish after some time
    #100;
    $finish;
end

// DUT instantiation
hex_to_rtl_top
dut (
    .clk            (clk),
    .rst            (rst),
    .data_in        (data_in),
    .data_in_sop    (data_in_sop),
    .data_in_eop    (data_in_eop),
    .data_in_valid  (data_in_valid),
    .data_in_ready  (data_in_ready),
    .path_id_out_ready (path_id_out_ready),
    .path_id_out    (path_id_out),
    .path_id_out_valid (path_id_out_valid)
);

// Scoreboard
logic [13-1:0] dut_q[$];

//store the data from dut into dut_q
always_ff @ (posedge clk) begin
    if (path_id_out_valid) begin
        dut_q.push_back(path_id_out);
    end
end

always_ff @ (posedge clk) begin
    if (dut_q.size() > 0 && golden_q.size() > 0) begin
        logic [13-1:0] act = dut_q.pop_front();
        logic [13-1:0] exp = golden_q.pop_front();

        if (act != exp) begin
            $display ("[%0t] MISMATCH: Got %0h, Expected %0h", $time, act, exp);
        end else begin
            $display ("[%0t] MATCH: %0h", $time, act);
        end
    end
end

endmodule: hex_to_rtl_top_tb
